-- 00_PRECHECK_CLOUD.sql — READ-ONLY 선판정 [E20260930-DMF0049SETFULL2] · 빌드 2026-09-30 20:02 · 원천 사내 ZIOUI1
--  ⚠ QA · DEV 두 DB 모두 · JUDGE 가 '적용'/'SKIP' 이 아니면 11 을 적용하지 말고 12 수동 반영(README §4)
SET PAGESIZE 200 LINESIZE 250
COLUMN JUDGE FORMAT A90
PROMPT [E0] 접속 DB
SELECT USER USR, SYS_CONTEXT('USERENV','DB_NAME') DB_NAME, SYS_CONTEXT('USERENV','SERVER_HOST') HOST FROM DUAL;
PROMPT [H] PKG_DMF0049 BODY 지문 — 전 1300/71477 (= SETFULL 1차 적용본) · 후 1293/71032
SELECT LN || '/' || CH BODY_FP, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0049' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%/*[E20260930-DMF0049SETFULL] 메저 세트 보충%') MARK_SETFULL1_BLOCK, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0049' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%/*[E20260930-DMF0049SETFULL2]%') MARK_SETFULL2,
       CASE WHEN LN = 1293 AND CH = 71032 THEN 'SKIP — 이미 적용됨'
            WHEN LN = 1300 AND CH = 71477 THEN '적용 — 05 → 11 → 90'
            WHEN (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0049' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%/*[E20260930-DMF0049SETFULL] 메저 세트 보충%') = 0 AND (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0049' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%/*[E20260930-DMF0049SETFULL2]%') = 0 THEN '⚠ 중단 — SETFULL 1차 미적용: DMF0049_SETFULL_CLOUD_20260930 대신 본 패키지 12 를 수동 반영하거나 결과 회신'
            ELSE '⚠ 11 적용 금지 — 지문 상이(타 작업자 변경). 12 를 수동 반영 (README §4)' END JUDGE
  FROM (SELECT COUNT(*) LN, SUM(LENGTH(RTRIM(TEXT, CHR(10)||CHR(13)))) CH FROM USER_SOURCE WHERE NAME='PKG_DMF0049' AND TYPE='PACKAGE BODY' AND LINE > 1);
